import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.CZqXuAiL.js";const k=JSON.parse('{"title":"Webhooks & Alerts","description":"Panel Firewall webhook notifications — Discord-compatible alerts for attacks, mitigations, applies, and rollbacks, with HMAC secrets and SSRF protection.","frontmatter":{"title":"Webhooks & Alerts","description":"Panel Firewall webhook notifications — Discord-compatible alerts for attacks, mitigations, applies, and rollbacks, with HMAC secrets and SSRF protection."},"headers":[],"relativePath":"panel-firewall/user-guide/webhooks.md","filePath":"panel-firewall/user-guide/webhooks.md","lastUpdated":1785522036000}'),o={name:"panel-firewall/user-guide/webhooks.md"};function n(l,e,r,d,h,c){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="webhooks-alerts" tabindex="-1">Webhooks &amp; Alerts <a class="header-anchor" href="#webhooks-alerts" aria-label="Permalink to &quot;Webhooks &amp; Alerts&quot;">​</a></h1><p>Panel Firewall can POST JSON events to Discord-compatible webhook URLs when things happen — attacks detected, mitigations applied/cleared, firewall applied or rolled back. Webhooks are managed in <strong>Admin → Panel Firewall → Webhooks</strong> and synced to the daemon on save.</p><hr><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><ol><li>In Discord: <strong>Server Settings → Integrations → Webhooks → New Webhook</strong>, copy the URL.</li><li>In the panel: <strong>Admin → Panel Firewall → Webhooks → Add webhook</strong>.</li><li>Paste the URL, pick the events you care about, optionally set a secret, save.</li><li>The panel pushes the webhook set to the daemon (<code>POST /api/v1/webhooks/sync</code>). Done — the next event fires a delivery.</li></ol><div class="warning custom-block"><p class="custom-block-title">URL restrictions (SSRF protection)</p><p>Webhook URLs must be <strong>HTTPS</strong> and resolve to <strong>public IP addresses only</strong>. The panel resolves <em>all</em> A records, rejects the URL if any is private/reserved (loopback, RFC-1918, link-local, cloud metadata <code>169.254.169.254</code>), and pins the validated IP for the actual request so DNS-rebinding can&#39;t redirect it at your internal network. If your Discord URL is rejected, that&#39;s why.</p></div><hr><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>Fired when</th></tr></thead><tbody><tr><td><code>attack_detected</code></td><td>SMART EWMA detector flags an anomaly (includes level, confidence, metrics)</td></tr><tr><td><code>mitigation_enabled</code></td><td>A mitigation level (L1–L3) is applied</td></tr><tr><td><code>mitigation_disabled</code></td><td>Mitigation cleared — cooldown expired or SMART disabled</td></tr><tr><td><code>firewall_applied</code></td><td>A successful transactional apply</td></tr><tr><td><code>firewall_rollback</code></td><td>Manual rollback, or the 60s confirm window expired</td></tr><tr><td><code>reconcile_drift</code></td><td>The reconcile loop finds kernel state diverging from desired state</td></tr></tbody></table><p>The panel also dispatches its own hooks on apply, confirm, and manual rollback, so events still fire for panel-initiated actions even if the daemon is mid-transaction.</p><h2 id="payload" tabindex="-1">Payload <a class="header-anchor" href="#payload" aria-label="Permalink to &quot;Payload&quot;">​</a></h2><p>Each delivery is a JSON POST with the event name, timestamp, severity, and a details object (e.g. anomaly metrics and confidence for attacks, checkpoint id for applies). If a <strong>secret</strong> is set, the payload is HMAC-signed so your receiver can verify authenticity.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;event&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;attack_detected&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;at&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1754000000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;actor&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;daemon:smart&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;details&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;level&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;confidence&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.71</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;anomalies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;metric&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;cps_in&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;confidence&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.71</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><hr><h2 id="delivery-behavior" tabindex="-1">Delivery behavior <a class="header-anchor" href="#delivery-behavior" aria-label="Permalink to &quot;Delivery behavior&quot;">​</a></h2><ul><li><strong>Retries</strong> — failed deliveries are retried with backoff before being marked failed</li><li><strong>Rate limited</strong> — a flood of events can&#39;t flood your Discord channel</li><li><strong>Logged</strong> — every attempt lands in the daemon&#39;s <code>webhook_log</code>; view it in the admin UI or via <code>GET /api/v1/webhooks/log</code> (<code>at</code>, <code>event</code>, <code>url</code>, <code>statusCode</code>, <code>outcome</code>)</li></ul><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><details class="details custom-block"><summary>No deliveries at all</summary><p>Check the webhook log in the admin UI. <code>outcome=failed</code> with a DNS error means the URL didn&#39;t resolve; <code>statusCode=401/404</code> means the Discord webhook was deleted or the URL is wrong — regenerate it.</p></details><details class="details custom-block"><summary>&quot;URL rejected&quot; when saving</summary><p>The URL failed the SSRF guard: not HTTPS, or it resolves to a private/reserved IP. Discord webhooks are public HTTPS — if a Discord URL is rejected, check the host&#39;s DNS (<code>dig discord.com</code>) for hijacked/filtered records.</p></details><details class="details custom-block"><summary>Deliveries stopped after an import</summary><p>Webhook <strong>secrets are never exported</strong> (bundles show <code>[REDACTED]</code>). After importing a bundle on a new install, re-enter the secrets manually.</p></details>`,21)])])}const u=s(o,[["render",n]]);export{k as __pageData,u as default};
